const EXPECTED_VERIFY_TOKEN = 'hyfo9876';
const q = $input.first().json.query || {};
const tokenOk = q['hub.verify_token'] === EXPECTED_VERIFY_TOKEN;
return [{ json: { challenge: q['hub.challenge'], tokenOk } }];

// Formato do webhook da Meta Cloud API. Statuses (sent/delivered/read) chegam no mesmo webhook sem 'messages'.
const body = $input.first().json.body || $input.first().json;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
const phone = String(msg?.from || '').replace(/\D/g, '');
const text = msg?.text?.body || (msg?.button?.text) || (msg?.interactive?.button_reply?.title) || (msg?.interactive?.list_reply?.title) || '';
const pushName = value?.contacts?.[0]?.profile?.name || '';
const phoneNumberId = String(value?.metadata?.phone_number_id || '');
const isMessage = Boolean(msg) && Boolean(phone);
const isText = isMessage && Boolean(text);
const modoTeste = phone.startsWith('5500');
return [{ json: { phone, text, pushName, isMessage, isText, modoTeste, phoneNumberId, messageId: msg?.id || '', messageType: msg?.type || '' } }];

const j=$input.first().json;
const texto = j.isText ? j.text : '[o cliente enviou uma mensagem do tipo ' + (j.messageType||'desconhecido') + ' sem texto; peça para escrever a dúvida em texto]';
return [{ json: { ...j, entrada: '[Cliente: ' + (j.pushName || 'sem nome') + ' | WhatsApp: ' + j.phone + '] ' + texto } }];

const j=$input.first().json||{}; const norm=$('Normalizar Mensagem').item.json;
let out = (typeof j.output === 'string' && j.output.trim()) ? j.output.trim() : '';
if (!out) out = 'Desculpe, tive um probleminha técnico para responder agora. Pode repetir sua mensagem? Se preferir, nossa equipe responde aqui mesmo em horário comercial.';
return [{ json: { phone: norm.phone, modoTeste: norm.modoTeste, resposta: out, agente_erro: j.error ? String(j.error.message || j.error).slice(0,200) : '' } }];
